assignments.value:
=={{
  [
    $json.data?.markdown,
    $json.data?.metadata?.description,
    $json.data?.metadata?.ogDescription
  ]
    .filter(value => typeof value === 'string' && value.trim())
    .sort((a, b) => b.trim().length - a.trim().length)[0]
    ?.trim() || ''
}}
